	@Test
	void serverQueryDoesNotContactLoopbackService() throws Exception {
		AtomicInteger requests = new AtomicInteger();
		HttpServer endpoint = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		endpoint.createContext("/sparql", exchange -> {
			requests.incrementAndGet();
			byte[] response = ("{\"head\":{\"vars\":[\"s\"]},\"results\":{\"bindings\":["
					+ "{\"s\":{\"type\":\"uri\",\"value\":\"urn:private\"}}]}}")
							.getBytes(StandardCharsets.UTF_8);
			exchange.getResponseHeaders().set("Content-Type", "application/sparql-results+json");
			exchange.sendResponseHeaders(200, response.length);
			try (var output = exchange.getResponseBody()) {
				output.write(response);
			}
		});
		endpoint.start();
		Repository repository = new SailRepository(new MemoryStore());
		repository.init();
		try {
			String service = "http://127.0.0.1:" + endpoint.getAddress().getPort() + "/sparql";
			MockHttpServletRequest request = new MockHttpServletRequest();
			request.setAttribute("repository", repository);
			try (RepositoryConnection connection = RepositoryInterceptor.getRepositoryConnection(request)) {
				Throwable failure = catchThrowable(() -> {
					try (TupleQueryResult result = connection.prepareTupleQuery(QueryLanguage.SPARQL,
							"SELECT ?s WHERE { SERVICE <" + service + "> { ?s ?p ?o } }").evaluate()) {
						result.hasNext();
					}
				});
				assertThat(requests).hasValue(0);
				assertThat(failure).hasStackTraceContaining("SERVICE endpoint denied");
			}
		} finally {
			repository.shutDown();
			endpoint.stop(0);
		}
	}

