	@Test
	void silentOptionalUnionAndExistsStillRejectPrivateService() throws Exception {
		try (LocalEndpoint endpoint = new LocalEndpoint()) {
			Repository repository = new SailRepository(new MemoryStore());
			repository.init();
			try {
				MockHttpServletRequest request = new MockHttpServletRequest();
				request.setAttribute("repository", repository);
				String service = endpoint.url();
				try (RepositoryConnection connection = RepositoryInterceptor.getRepositoryConnection(request)) {
					try (TupleQueryResult result = connection.prepareTupleQuery(QueryLanguage.SPARQL,
							"SELECT ?seed WHERE { VALUES ?seed { <urn:seed> } "
									+ "SERVICE SILENT <" + service + "> { ?s ?p ?o } }")
							.evaluate()) {
						assertThat(result.hasNext()).isTrue();
						assertThat(result.next().getValue("seed").stringValue()).isEqualTo("urn:seed");
					}
					assertThat(endpoint.requests).hasValue(0);
					assertDenied(connection,
							"SELECT ?s WHERE { VALUES ?seed { <urn:seed> } OPTIONAL { SERVICE <" + service
									+ "> { ?s ?p ?o } } }",
							endpoint.requests);
					assertDenied(connection,
							"SELECT ?s WHERE { { SERVICE <" + service + "> { ?s ?p ?o } } "
									+ "UNION { VALUES ?s { <urn:local> } } }",
							endpoint.requests);
					assertDenied(connection,
							"SELECT ?s WHERE { VALUES ?s { <urn:seed> } "
									+ "FILTER EXISTS { SERVICE <" + service + "> { ?x ?p ?o } } }",
							endpoint.requests);
				}
			} finally {
				repository.shutDown();
			}
		}
	}

