	@Test
	void concurrentEmbeddedConnectionRetainsItsOwnServiceResolver() throws Exception {
		try (LocalEndpoint endpoint = new LocalEndpoint()) {
			Repository repository = new SailRepository(new MemoryStore());
			repository.init();
			try {
				MockHttpServletRequest request = new MockHttpServletRequest();
				request.setAttribute("repository", repository);
				String query = "SELECT ?s WHERE { SERVICE <" + endpoint.url() + "> { ?s ?p ?o } }";
				try (RepositoryConnection embedded = repository.getConnection();
						RepositoryConnection server = RepositoryInterceptor.getRepositoryConnection(request)) {
					assertThat(querySubject(embedded, query)).isEqualTo("urn:private");
					assertThat(endpoint.requests).hasValue(1);
					assertDenied(server, query, endpoint.requests, 1);
					assertThat(querySubject(embedded, query)).isEqualTo("urn:private");
					assertThat(endpoint.requests).hasValue(2);
				}
			} finally {
				repository.shutDown();
			}
		}
	}

